127	interface ParsedOptions {
128	  devices: string[];
129	  from?: number;
130	  to?: number;
131	}
132	
133	/** 解析 --device/--from/--to 选项;出错返回错误消息字符串。 */
134	function parseOptions(rest: string[]): ParsedOptions | string {
135	  const devices: string[] = [];
136	  let from: number | undefined;
137	  let to: number | undefined;
138	  for (let i = 0; i < rest.length; i++) {
139	    let opt = rest[i];
140	    let value: string | undefined;
141	    const eq = opt.indexOf('=');
142	    if (opt.startsWith('--') && eq !== -1) {
143	      value = opt.slice(eq + 1);
144	      opt = opt.slice(0, eq);
145	    } else if (opt.startsWith('--')) {
146	      value = rest[i + 1];
147	      if (value === undefined) return `选项 '${opt}' 缺少值`;
148	      i++;
149	    } else {
150	      return `无法识别的参数 '${opt}'`;
151	    }
152	    if (opt === '--device') {
153	      if (value.trim() === '') return "'--device' 的值不能为空";
154	      devices.push(value);
155	    } else if (opt === '--from' || opt === '--to') {
156	      const ts = parseIso8601(value.trim());
157	      if (ts === null) {
158	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
159	      }
160	      if (opt === '--from') from = ts;
161	      else to = ts;
162	    } else {
163	      return `无法识别的选项 '${opt}'`;
164	    }
165	  }
166	  return { devices, from, to };
167	}
168	
169	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
170	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
171	  const out = new Map<string, string[]>();
172	  for (let i = 0; i < rest.length; i++) {
173	    let opt = rest[i];
174	    let value: string | undefined;
175	    const eq = opt.indexOf('=');
176	    if (opt.startsWith('--') && eq !== -1) {
177	      value = opt.slice(eq + 1);
178	      opt = opt.slice(0, eq);
179	    } else if (opt.startsWith('--')) {
180	      value = rest[i + 1];
181	      if (value === undefined) return `选项 '${opt}' 缺少值`;
182	      i++;
183	    } else {
184	      return `无法识别的参数 '${opt}'`;
185	    }
186	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
187	    const list = out.get(opt);
188	    if (list) list.push(value);
189	    else out.set(opt, [value]);
190	  }
191	  return out;
192	}
193	
194	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
195	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
196	  const list = flags.get(name);
197	  if (!list || list.length !== 1) return null;
198	  return list[0];
199	}
200	
201	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
202	function dateFlag(value: string, label: string): number | string {
203	  const ts = parseUtcDate(value.trim());
204	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
205	  return ts;
206	}
207	
208	function cmdRule(rest: string[]): number {
209	  const [sub, ...subrest] = rest;
210	  if (sub === 'list') {
211	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
212	    return cmdRuleList();
213	  }
214	  if (sub === 'create') {
215	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold']);
216	    if (typeof flags === 'string') return usageError(flags);
217	    const idRaw = oneFlag(flags, '--id');
218	    const deviceList = flags.get('--device');
219	    const groupList = flags.get('--group');
220	    const thresholdRaw = oneFlag(flags, '--threshold');
221	    if (idRaw === null || thresholdRaw === null) {
222	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
223	    }
224	    const hasDevice = deviceList !== undefined;
225	    const hasGroup = groupList !== undefined;
226	    if (hasDevice === hasGroup) {
227	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
228	    }
229	    if ((deviceList !== undefined && deviceList.length !== 1) ||
230	      (groupList !== undefined && groupList.length !== 1)) {
231	      return usageError("'rule create' 的目标选项只能出现一次");
232	    }
233	    const id = idRaw.trim();
234	    if (id === '') return usageError('规则标识不能为空');
235	    const thresholdMilli = parseKwh(thresholdRaw.trim());
236	    if (thresholdMilli === null) {
237	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
238	    }
239	    if (hasDevice) {
240	      const device = (deviceList as string[])[0].trim();
241	      if (device === '') return usageError("'--device' 的值不能为空");
242	      return cmdRuleCreate({ id, targetType: 'device', targetId: device, thresholdMilli });
243	    }
244	    const group = (groupList as string[])[0].trim();
245	    if (group === '') return usageError("'--group' 的值不能为空");
246	    return cmdRuleCreate({ id, targetType: 'group', targetId: group, thresholdMilli });
247	  }
248	  if (sub === undefined) return usageError("'rule' 需要子命令 create 或 list");
249	  return usageError(`无法识别的 rule 子命令 '${sub}'`);
250	}
251	
252	function cmdEvaluateEntry(rest: string[]): number {
253	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
254	  if (typeof flags === 'string') return usageError(flags);
255	  const ruleRaw = oneFlag(flags, '--rule');
256	  const fromRaw = oneFlag(flags, '--from');
257	  const toRaw = oneFlag(flags, '--to');
258	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
259	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
260	  }
261	  const ruleId = ruleRaw.trim();
262	  if (ruleId === '') return usageError('规则标识不能为空');
263	  const from = dateFlag(fromRaw, '起始日期');
264	  if (typeof from === 'string') return usageError(from);
265	  const to = dateFlag(toRaw, '结束日期');
266	  if (typeof to === 'string') return usageError(to);
267	  if (from >= to) return usageError('评估起日必须早于止日(--from < --to)');
268	  return cmdEvaluate({ ruleId, from, to });
269	}
270	
271	function cmdAlertsEntry(rest: string[]): number {
272	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
273	  if (typeof flags === 'string') return usageError(flags);
274	  const ruleRaw = oneFlag(flags, '--rule');
275	  if (ruleRaw === null) return usageError("'alerts' 需要 --rule 恰好一个");
276	  const ruleId = ruleRaw.trim();
277	  if (ruleId === '') return usageError('规则标识不能为空');
278	  const fromList = flags.get('--from');
279	  const toList = flags.get('--to');
280	  if ((fromList !== undefined) !== (toList !== undefined)) {
281	    return usageError("'alerts' 的 --from 与 --to 需同时提供或同时省略");
282	  }
283	  let from: number | undefined;
284	  let to: number | undefined;
285	  if (fromList !== undefined) {
286	    const fromRaw = oneFlag(flags, '--from');
287	    const toRaw = oneFlag(flags, '--to');
288	    if (fromRaw === null || toRaw === null) {
289	      return usageError("'alerts' 的 --from 与 --to 各只能出现一次");
290	    }
291	    const fromParsed = dateFlag(fromRaw, '起始日期');
292	    if (typeof fromParsed === 'string') return usageError(fromParsed);
293	    const toParsed = dateFlag(toRaw, '结束日期');
294	    if (typeof toParsed === 'string') return usageError(toParsed);
295	    if (fromParsed >= toParsed) return usageError('查询起日必须早于止日(--from < --to)');
296	    from = fromParsed;
297	    to = toParsed;
298	  }
299	  return cmdAlerts({ ruleId, from, to });
300	}
301	
302	function cmdGroup(rest: string[]): number {
303	  const [sub, ...subrest] = rest;
304	  if (sub === 'configure') {
305	    const flags = parseFlags(subrest, ['--id', '--at', '--device']);
306	    if (typeof flags === 'string') return usageError(flags);
307	    const idRaw = oneFlag(flags, '--id');
308	    const atRaw = oneFlag(flags, '--at');
309	    const deviceList = flags.get('--device') ?? [];
310	    if (idRaw === null || atRaw === null) {
311	      return usageError("'group configure' 需要 --id 与 --at 各恰好一个");
312	    }
313	    if (deviceList.length === 0) {
314	      return usageError("'group configure' 需要至少一个 --device(成员不能为空)");
315	    }
316	    const id = idRaw.trim();
317	    if (id === '') return usageError('分组标识不能为空');
318	    const at = parseIso8601(atRaw.trim());
319	    if (at === null) {
320	      return usageError(
321	        `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`,
322	      );
323	    }
324	    const members: string[] = [];
325	    for (const d of deviceList) {
326	      const m = d.trim();
327	      if (m === '') return usageError("'--device' 的值不能为空");
328	      members.push(m);
329	    }
330	    return cmdGroupConfigure({ id, at, members });
331	  }
332	  if (sub === 'history') {
333	    const flags = parseFlags(subrest, ['--id']);
334	    if (typeof flags === 'string') return usageError(flags);
335	    const idRaw = oneFlag(flags, '--id');
336	    if (idRaw === null) return usageError("'group history' 需要 --id 恰好一个");
337	    const id = idRaw.trim();
338	    if (id === '') return usageError('分组标识不能为空');
339	    return cmdGroupHistory({ id });
340	  }
341	  if (sub === 'daily') {
342	    const flags = parseFlags(subrest, ['--id', '--from', '--to']);
343	    if (typeof flags === 'string') return usageError(flags);
344	    const idRaw = oneFlag(flags, '--id');
345	    const fromRaw = oneFlag(flags, '--from');
346	    const toRaw = oneFlag(flags, '--to');
347	    if (idRaw === null || fromRaw === null || toRaw === null) {
348	      return usageError("'group daily' 需要 --id、--from、--to 各恰好一个(起点含、终点不含)");
349	    }
350	    const id = idRaw.trim();
351	    if (id === '') return usageError('分组标识不能为空');
352	    const from = parseIso8601(fromRaw.trim());
353	    if (from === null) {
354	      return usageError(`选项 '--from' 的时间无效: '${fromRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`);
355	    }
356	    const to = parseIso8601(toRaw.trim());
357	    if (to === null) {
