1	// 本地持久化:JSON 文件,默认位于 ~/.meterwatch/readings.json,
2	// 可用环境变量 METERWATCH_DATA_DIR 指定其他目录。
3	// 写入采用临时文件 + rename 的原子方式;读取失败或内容损坏一律报错,绝不当作空库。
4	//
5	// 毫千瓦时数值在文件中以十进制字符串保存,可表示任意大的精确值;
6	// 同时兼容旧版以 JSON 数值保存的安全整数读数。数值型毫千瓦时若超出
7	// Number 安全整数范围,JSON 解析时已丢失精度,按损坏数据拒绝,不猜测原值。
8	
9	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
10	import { homedir } from 'node:os';
11	import { dirname, join } from 'node:path';
12	
13	export interface Reading {
14	  /** 设备标识(已去除首尾空白,区分大小写)。 */
15	  device: string;
16	  /** 实际时刻,epoch 秒。 */
17	  ts: number;
18	  /** 累计读数,毫千瓦时(千分之一 kWh)BigInt,非负。 */
19	  milli: bigint;
20	}
21	
22	export class StoreError extends Error {}
23	
24	export function dataFilePath(): string {
25	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
26	  return join(dir, 'readings.json');
27	}
28	
29	/** 告警规则与历史的存储文件,与读数文件同目录、相互独立。 */
30	export function alertFilePath(): string {
31	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
32	  return join(dir, 'alerts.json');
33	}
34	
35	/** 分组配置的存储文件,与读数、告警文件同目录、相互独立。 */
36	export function groupFilePath(): string {
37	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
38	  return join(dir, 'groups.json');
39	}
40	
41	/**
42	 * 解析存储中的毫千瓦时字段:十进制数字字符串,或旧格式的安全整数数值。
43	 * 其他形式(含超出安全整数范围的数值,精度已丢失)返回 null,由调用方按损坏处理。
44	 */
45	export function parseStoredMilli(value: unknown): bigint | null {
46	  if (typeof value === 'string' && /^\d+$/.test(value)) return BigInt(value);
47	  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) {
48	    return BigInt(value);
49	  }
50	  return null;
51	}
52	
53	/** 读取存储;文件不存在返回空数组,存在但无法读取或内容损坏抛出 StoreError。 */
54	export function loadStore(path: string): Reading[] {
55	  let text: string;
56	  try {
57	    text = readFileSync(path, 'utf8');
58	  } catch (err) {
59	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return [];
60	    throw new StoreError(`cannot read storage file ${path}: ${(err as Error).message}`);
61	  }
62	  let data: unknown;
63	  try {
64	    data = JSON.parse(text);
65	  } catch {
66	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
67	  }
