// correct 与 corrections 两个子命令的实现:可追溯的已存读数批量修正。

import {
  dataFilePath, loadData, saveData, StoreError,
  type Correction, type CorrectionItem, type Reading,
} from './store.ts';
import { loadCheckedSeriesByDevice } from './groups.ts';
import { formatIsoUtc } from './time.ts';
import { formatKwh } from './value.ts';

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

function sameItem(a: CorrectionItem, b: CorrectionItem): boolean {
  return a.device === b.device && a.ts === b.ts &&
    a.expectedMilli === b.expectedMilli && a.replacementMilli === b.replacementMilli;
}

function itemsEquivalent(a: CorrectionItem[], b: CorrectionItem[]): boolean {
  if (a.length !== b.length) return false;
  const used = new Array(b.length).fill(false);
  for (const item of a) {
    let found = false;
    for (let j = 0; j < b.length; j++) {
      if (!used[j] && sameItem(item, b[j])) { used[j] = true; found = true; break; }
    }
    if (!found) return false;
  }
  return true;
}

function changedCount(items: CorrectionItem[]): number {
  return items.filter((i) => i.expectedMilli !== i.replacementMilli).length;
}

function reportSuccess(requestId: string, items: CorrectionItem[]): void {
  console.log(`correction '${requestId}' committed: ${items.length} item(s), ${changedCount(items)} reading(s) changed`);
}

export function cmdCorrect(requestId: string, items: CorrectionItem[]): number {
  // 同批同一读数身份只允许一项(参数错误)。
  const seen = new Set<string>();
  for (const it of items) {
    const k = `${it.device} ${it.ts}`;
    if (seen.has(k)) {
      err(`duplicate correction item for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
      return 2;
    }
    seen.add(k);
  }

  const storePath = dataFilePath();
  let data;
  try { data = loadData(storePath); } catch (e) { ... return 1; }

  // 重放:同标识同内容直接返回原成功结果;同标识异内容报冲突。
  const prior = data.corrections.find((c) => c.requestId === requestId);
  if (prior !== undefined) {
    if (itemsEquivalent(prior.items, items)) {
      reportSuccess(requestId, prior.items);
      return 0;
    }
    err(`correction request '${requestId}' already committed with different content; nothing was changed`);
    return 1;
  }

  // 全库重复身份拒绝。
  let byDevice;
  try { byDevice = loadCheckedSeriesByDevice(data.readings); }
  catch (e) { if (e instanceof StoreError) { err(e.message); return 1; } throw e; }

  // 核验:身份存在且预期原值与当前已存值精确一致。
  const errors: string[] = [];
  const targets: Array<{ reading: Reading; item: CorrectionItem }> = [];
  for (const it of items) {
    const series = byDevice.get(it.device);
    const reading = series?.find((r) => r.ts === it.ts);
    if (!reading) {
      errors.push(`no stored reading for device '${it.device}' at ${formatIsoUtc(it.ts)}`);
      continue;
    }
    if (reading.milli !== it.expectedMilli) {
      errors.push(`stored value mismatch for device '${it.device}' at ${formatIsoUtc(it.ts)}: expected ${formatKwh(it.expectedMilli)} kWh but stored ${formatKwh(reading.milli)} kWh`);
      continue;
    }
    targets.push({ reading, item: it });
  }
  if (errors.length > 0) {
    for (const e of errors) err(e);
    err(`correction '${requestId}' rejected: ${errors.length} item(s) failed; nothing was changed`);
    return 1;
  }

  for (const { reading, item } of targets) reading.milli = item.replacementMilli;
  const corrections = data.corrections.concat([{ requestId, items }]);
  try { saveData(storePath, { readings: data.readings, corrections }); }
  catch ... return 1;
  reportSuccess(requestId, items);
  return 0;
}

export function cmdCorrections(): number {
  load, print.
}
```

